CREATE TABLE foods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, carbohydrates numeric NOT NULL DEFAULT 0, protein numeric NOT NULL DEFAULT 0, fat numeric NOT NULL DEFAULT 0, calories numeric NOT NULL DEFAULT 0, fiber numeric NOT NULL DEFAULT 0, is_favorite boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alert_preferences (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, low_threshold numeric NOT NULL DEFAULT 70, high_threshold numeric NOT NULL DEFAULT 180, reminders_enabled boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
